const dateFromKey=(key:string)=>{const [y,m,d]=key.split("-").map(Number);return new Date(y,m-1,d,12)};
const offsetDate=(offset:number)=>{const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()+offset);return dateKey(date)};
