 function addService(){if(!newService.trim())return;const service:Service={id:uid(),name:newService.trim(),price:newServicePrice,duration:newServiceDuration,active:true,description:"",images:newServiceImage?[newServiceImage]:[],questionIds:[]};setData(d=>({...d,services:[...d.services,service]}));setPortfolioService(service.id);setNewService("");setNewServicePrice(20000);setNewServiceDuration(120);setNewServiceImage("");}
